export interface CreateDataRoomBodySettings {
  /** Watermark every page with the viewer's e-mail. New rooms: true. Pro and higher. true / false (also 1 / 0 or "true" / "false"). */
  watermark?: boolean;
  /** Allow download & print. New rooms: false (read in the browser only). true / false (also 1 / 0 or "true" / "false"). */
  download?: boolean;
  /** Screenshot protection. New rooms: false. Pro and higher. true / false (also 1 / 0 or "true" / "false"). */
  screenshot_protection?: boolean;
  /** E-mail guests (the invitation and new-document notices). New rooms: true. true / false (also 1 / 0 or "true" / "false"). */
  notify?: boolean;
  /** Last day guests have access (YYYY-MM-DD, today or later – a day in the past is refused); null or "" = no expiry. Pro and higher. */
  expires_on?: string | null;
  /** Guests accept an NDA before any document. Max and higher, Deal Room Pass, trial. true without nda_id uses nda_template; false turns the NDA off. true / false (also 1 / 0 or "true" / "false"). */
  nda?: boolean;
  /** One of your NDAs (List NDAs); implies nda true. */
  nda_id?: number;
  /** Without nda_id: HelpRange's NDA template, added to your NDAs once. Default investor. */
  nda_template?: "investor" | "ma";
  /** click: one-click acceptance (new rooms' default); signature: typed signature with a sealed PDF. */
  nda_mode?: "signature" | "click";
  /** Guests can ask questions. Max and higher. true / false (also 1 / 0 or "true" / "false"). */
  qa?: boolean;
  /** Anyone with the room's guest_link can request access. Max and higher. true / false (also 1 / 0 or "true" / "false"). */
  access_requests?: boolean;
  /** Room folders on / off (off deletes the room's folders; documents stay in the room). true / false (also 1 / 0 or "true" / "false"). */
  folders_enabled?: boolean;
}

