export interface CreateOfferResponse {
  id: number;
  title: string;
  status: "draft" | "active" | "accepted" | "declined" | "expired" | "closed";
  expired: boolean;
  client: OfferClient;
  kind: string;
  /** The offer link to send to the client. */
  url: string;
  document_views: number;
  page_visits: number;
  last_viewed_at: string | null;
  sent_at: string | null;
  created_at: string;
  updated_at: string;
  stored_status: string;
  public_url: string;
  panel_url: string;
  message: string;
  price_summary: string;
  buttons: CreateOfferResponseButtons;
  protection: CreateOfferResponseProtection;
  open_directly: boolean;
  layout: string;
  theme: string;
  base_folder: ListFoldersResponseFolder | null;
  own_folder: ListFoldersResponseFolder | null;
  files: Array<CreateOfferResponseFile>;
  people: number;
  engagement: number | null;
  responses_count: number;
  responses: Array<OfferResponse>;
  sent_to: string | null;
  created_by: string | null;
  legacy_url: string | null;
  send_by_email: string;
  /** false for test-mode (hr_test_) keys, true for live keys. */
  livemode?: boolean;
}

/** Same shape as CreateOfferResponse. */
export type GetOfferResponse = CreateOfferResponse;

/** Request body of Update an offer. */
export interface UpdateOfferBody {
  /** What the client sees as the title. Create: default the folder's / first document's name. */
  title?: string;
  client_first_name?: string;
  client_last_name?: string;
  client_company?: string;
  /** The client's e-mail – never e-mailed by the API. */
  client_email?: string;
  /** Message on the offer page. */
  message?: string;
  /** One line, e.g. "3 packages, from 2,400 EUR". */
  price_summary?: string;
  /** "Accept offer" button (default on). */
  show_accept?: boolean;
  accept_label?: string;
  /** "Request contact" button (default on). */
  show_contact?: boolean;
  contact_label?: string;
  /** "Decline" button with an optional reason (default off). */
  show_decline?: boolean;
  decline_label?: string;
  /** The client verifies their e-mail with a one-time code (default on). */
  require_email_verification?: boolean;
  /** With e-mail verification: anyone, only client_email, or client_email and colleagues at the same domain. */
  access?: "any" | "email" | "domain";
  allow_download?: boolean;
  watermark?: boolean;
  /** Last day, YYYY-MM-DD ("" removes it). */
  expires_on?: string;
  /** Asked before the offer opens ("" removes it). */
  passcode?: string;
  /** Pro and higher (else 402). */
  screenshot_protection?: boolean;
  one_viewer_at_a_time?: boolean;
  /** One-file offers: open the document directly instead of the offer page. */
  open_directly?: boolean;
  layout?: "classic" | "split" | "cover" | "minimal";
  /** active also reopens an accepted, declined or archived offer; closed = archived. */
  status?: "active" | "draft" | "accepted" | "declined" | "closed";
}

/** Same shape as CreateOfferResponse. */
export type UpdateOfferResponse = CreateOfferResponse;

/** Request body of Add documents to an offer. */
export interface AddOfferFilesBody {
  /** Document ids. */
  file_ids: Array<number>;
}

/** Same shape as CreateOfferResponse. */
export type AddOfferFilesResponse = CreateOfferResponse;

/** Request body of Remove documents from an offer. */
export interface RemoveOfferFilesBody {
  /** Document ids. */
  file_ids: Array<number>;
}

/** Same shape as CreateOfferResponse. */
export type RemoveOfferFilesResponse = CreateOfferResponse;

/** Query parameters of Responses to an offer. */
export interface ListResponsesOfOfferQuery {
  /** Only this kind of answer. */
  kind?: "accept" | "contact" | "decline";
  /** Answers of the last N days, 1–3650. */
  days?: number;
  /** 1–200 (default 50). */
  limit?: number;
}

export interface ListResponsesOfOfferResponse {
  responses: Array<OfferResponse>;
  /** false for test-mode (hr_test_) keys, true for live keys. */
  livemode?: boolean;
}

/** Query parameters of Offer responses. */
export interface ListOfferResponsesQuery {
  /** Only this kind of answer. */
  kind?: "accept" | "contact" | "decline";
  /** Answers of the last N days, 1–3650. */
  days?: number;
  /** 1–200 (default 50). */
  limit?: number;
}

/** Same shape as ListResponsesOfOfferResponse. */
export type ListOfferResponsesResponse = ListResponsesOfOfferResponse;

export interface ListWebhookEndpointsResponse {
  webhook_endpoints: Array<WebhookEndpoint>;
  /** false for test-mode (hr_test_) keys, true for live keys. */
  livemode?: boolean;
}

/** Request body of Create a webhook endpoint. */
export interface CreateWebhookEndpointBody {
  /** https only, a public internet address (localhost, private networks and cloud metadata addresses are refused: 400 url_not_public). */
  url: string;
}

export interface CreateWebhookEndpointResponse {
  id: number;
  url: string;
  /** false after 410 Gone or repeated failures – turn it back on with "enabled": true. */
  enabled: boolean;
  disabled_reason: "gone" | "failures" | null;
  disabled_at: string | null;
  consecutive_failures: number;
  last_success_at: string | null;
  secret_rotated_at: string | null;
  /** Until then the previous secret still signs (a second v1=). */
  previous_secret_expires_at: string | null;
  created_at: string;
  /** Event types sent to the endpoint (every event). */
  events: Array<string>;
  /** The signing secret (whsec_…) – returned only in this response, never again. Verify HelpRange-Signature with it. */
  secret: string;
  /** false for test-mode (hr_test_) keys, true for live keys. */
  livemode?: boolean;
}

/** WebhookEndpoint (plus livemode). */
export interface GetWebhookEndpointResponse extends WebhookEndpoint {
  /** false for test-mode (hr_test_) keys, true for live keys. */
  livemode?: boolean;
}

/** Request body of Change a webhook endpoint. */
export interface UpdateWebhookEndpointBody {
  /** https only, a public internet address (localhost, private networks and cloud metadata addresses are refused: 400 url_not_public). */
  url?: string;
  /** true: turn the endpoint back on. true / false (also 1 / 0 or "true" / "false"). */
  enabled?: boolean;
}

/** Same shape as GetWebhookEndpointResponse. */
export type UpdateWebhookEndpointResponse = GetWebhookEndpointResponse;

export interface DeleteWebhookEndpointResponse {
  deleted: boolean;
  id: number;
  /** false for test-mode (hr_test_) keys, true for live keys. */
  livemode?: boolean;
}

/** Same shape as CreateWebhookEndpointResponse. */
export type RotateWebhookSecretResponse = CreateWebhookEndpointResponse;

export interface SendWebhookTestEventResponse {
  id: number;
  /** HelpRange-Event-Id – the same on retries and redeliveries. */
  event_id: string;
  event_type: string;
  status: "pending" | "delivered" | "failed";
  test: boolean;
  attempts: number;
  last_status_code?: number | null;
  last_error?: string | null;
  last_duration_ms?: number | null;
  created_at: string;
  last_attempt_at?: string | null;
  next_attempt_at?: string | null;
  delivered_at?: string | null;
  /** The JSON sent (the webhook envelope). */
  payload?: Record<string, unknown>;
  delivered: boolean;
  /** false for test-mode (hr_test_) keys, true for live keys. */
  livemode?: boolean;
}

/** Query parameters of List webhook deliveries. */
export interface ListWebhookDeliveriesQuery {
  /** Only this status. */
  status?: "pending" | "delivered" | "failed";
  /** Items per page, 1–100 (default 100). */
  limit?: number;
  /** Page number, 1 or more (default 1). next_page in the response is the next one, or null. */
  page?: number;
}

export interface ListWebhookDeliveriesResponse {
  webhook_endpoint_id: number;
  retention_days: number;
  deliveries: Array<WebhookDelivery>;
  page: number;
  limit: number;
  /** Deliveries matching the filter. */
  total: number;
  next_page: number | null;
  /** false for test-mode (hr_test_) keys, true for live keys. */
  livemode?: boolean;
}

/** Same shape as SendWebhookTestEventResponse. */
export type RedeliverWebhookDeliveryResponse = SendWebhookTestEventResponse;

